    "name": "ic_launcher_foreground.xml",
    "language": "xml",
    "category": "Manifest & Resources",
    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<vector xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    android:width=\"108dp\"\n    android:height=\"108dp\"\n    android:viewportWidth=\"108\"\n    android:viewportHeight=\"108\">\n\n    <group\n        android:pivotX=\"54\"\n        android:pivotY=\"54\">\n\n        <!-- Outer Ambient Control Aura / Quiet Ring -->\n        <path\n            android:fillColor=\"#06B6D4\"\n            android:fillAlpha=\"0.12\"\n            android:pathData=\"M54,20 C72.78,20 88,35.22 88,54 C88,72.78 72.78,88 54,88 C35.22,88 20,72.78 20,54 C20,35.22 35.22,20 54,20 Z\" />\n\n        <path\n            android:fillColor=\"#3B82F6\"\n            android:fillAlpha=\"0.08\"\n            android:pathData=\"M54,26 C69.46,26 82,38.54 82,54 C82,69.46 69.46,82 54,82 C38.54,82 26,69.46 26,54 C26,38.54 38.54,26 54,26 Z\" />\n\n        <!-- Clean Modern Smartphone Silhouette -->\n        <!-- Outer Chassis -->\n        <path\n            android:fillColor=\"#111827\"\n            android:strokeColor=\"#1E293B\"\n            android:strokeWidth=\"1.5\"\n            android:pathData=\"M37,22 L71,22 A8,8 0 0 1 79,30 L79,78 A8,8 0 0 1 71,86 L37,86 A8,8 0 0 1 29,78 L29,30 A8,8 0 0 1 37,22 Z\" />\n\n        <!-- Screen Surface -->\n        <path\n            android:fillColor=\"#090D16\"\n            android:strokeColor=\"#0E7490\"\n            android:strokeWidth=\"1\"\n            android:pathData=\"M33,26 L75,26 A4,4 0 0 1 79,30 L79,78 A4,4 0 0 1 75,82 L33,82 A4,4 0 0 1 29,78 L29,30 A4,4 0 0 1 33,26 Z\" />\n\n        <!-- Top Status Bar Area: Fading / Dissolving into quiet dots -->\n        <!-- Subtle Top Status Bar Horizon Line -->\n        <path\n            android:strokeColor=\"#1E293B\"\n            android:strokeWidth=\"0.8\"\n            android:pathData=\"M34,36 L74,36\" />\n\n        <!-- Status Pill: Dissolving Clock/Status Line into Calm Dots -->\n        <!-- Solid Cyan line dissolving to the right -->\n        <path\n            android:strokeColor=\"#22D3EE\"\n            android:strokeWidth=\"1.6\"\n            android:strokeLineCap=\"round\"\n            android:pathData=\"M37,31 L47,31\" />\n\n        <!-- Fading status indicators (dots representing system quieting / hushed state) -->\n        <path\n            android:fillColor=\"#22D3EE\"\n            android:fillAlpha=\"0.8\"\n            android:pathData=\"M52,31 A1.2,1.2 0 1 0 52,31.01\" />\n\n        <path\n            android:fillColor=\"#38BDF8\"\n            android:fillAlpha=\"0.5\"\n            android:pathData=\"M58,31 A1.1,1.1 0 1 0 58,31.01\" />\n\n        <path\n            android:fillColor=\"#818CF8\"\n            android:fillAlpha=\"0.3\"\n            android:pathData=\"M64,31 A1.0,1.0 0 1 0 64,31.01\" />\n\n        <path\n            android:fillColor=\"#C084FC\"\n            android:fillAlpha=\"0.15\"\n            android:pathData=\"M70,31 A0.9,0.9 0 1 0 70,31.01\" />\n\n        <!-- Center System Control / Toggle Element: High-contrast Electric Cyan & Slate -->\n        <!-- Toggle Pill Track -->\n        <path\n            android:fillColor=\"#0F172A\"\n            android:strokeColor=\"#0284C7\"\n            android:strokeWidth=\"1.4\"\n            android:pathData=\"M43,48 L65,48 A7,7 0 0 1 72,55 L72,55 A7,7 0 0 1 65,62 L43,62 A7,7 0 0 1 36,55 L36,55 A7,7 0 0 1 43,48 Z\" />\n\n        <!-- Active Toggle Thumb with Neon Glow (Electric Cyan Accent) -->\n        <path\n            android:fillColor=\"#22D3EE\"\n            android:pathData=\"M65,55 A5,5 0 1 0 55,55 A5,5 0 1 0 65,55 Z\" />\n\n        <!-- Concentric Hushing / Calming Wave below control -->\n        <!-- Subtle Shield / Protection arc guarding background apps -->\n        <path\n            android:strokeColor=\"#6366F1\"\n            android:strokeWidth=\"1.2\"\n            android:strokeLineCap=\"round\"\n            android:strokeAlpha=\"0.7\"\n            android:pathData=\"M46,70 C51,73.5 57,73.5 62,70\" />\n\n        <path\n            android:strokeColor=\"#38BDF8\"\n            android:strokeWidth=\"1.0\"\n            android:strokeLineCap=\"round\"\n            android:strokeAlpha=\"0.5\"\n            android:pathData=\"M49,74 C52,76 56,76 59,74\" />\n\n    </group>\n</vector>\n"
